import{_ as n,C as s,o as e,c as o,ai as i,j as l,a,E as d}from"./chunks/framework.D78JMWkX.js";const p="/OS_Learning/assets/image-3.BfY4VpxM.png",h="/OS_Learning/assets/image-2.Cr0OMwkM.png",g="/OS_Learning/assets/image-1.Cgqrqi6Y.png",S=JSON.parse('{"title":"==请求式分页系统==","description":"","frontmatter":{},"headers":[],"relativePath":"内存管理/3_5 请求式分页系统.md","filePath":"内存管理/3_5 请求式分页系统.md","lastUpdated":1781416353000}'),u={name:"内存管理/3_5 请求式分页系统.md"},m={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},c={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"0.781ex",height:"1.52ex",role:"img",focusable:"false",viewBox:"0 -661 345 672","aria-hidden":"true"},x={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},T={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"0"},xmlns:"http://www.w3.org/2000/svg",width:"2.652ex",height:"0.271ex",role:"img",focusable:"false",viewBox:"0 -120 1172 120","aria-hidden":"true"},b={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},_={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.09ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.509ex",height:"1.312ex",role:"img",focusable:"false",viewBox:"0 -540 667 580","aria-hidden":"true"};function w(f,t,k,Q,q,P){const r=s("QuizSet");return e(),o("div",null,[t[13]||(t[13]=i('<h1 id="请求式分页系统" tabindex="-1">==请求式分页系统== <a class="header-anchor" href="#请求式分页系统" aria-label="Permalink to &quot;==请求式分页系统==&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><strong>进程的逻辑地址空间（虚拟地址空间）：</strong></li><li>一个进程的逻辑空间的建立是通过链接器（Linker），将构成进程所需要的所有程序及运行所需环境，按照某种规则装配链接而形成的一种规范格式(布局)</li><li><strong>交换分区（交换文件）：</strong></li><li>一段连续的磁盘空间（按页划分的），并且对用户不可见。它的功能就是在物理内存不够的情况下，操作系统先把内存中暂时不用的数据，存到硬盘的交换空间，腾出物理内存来让别的程序运行（Linux中为swap，Windows中则以文件<code>pagefile.sys</code>形式存在）</li></ul></div><h2 id="地址映射" tabindex="-1">地址映射 <a class="header-anchor" href="#地址映射" aria-label="Permalink to &quot;地址映射&quot;">​</a></h2><p>​ <strong>请求式分页管理页表表项</strong></p><p>逻辑页号</p><p>↓</p>',6)),l("p",null,[l("mjx-container",m,[(e(),o("svg",c,[...t[0]||(t[0]=[l("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[l("g",{"data-mml-node":"math"},[l("g",{"data-mml-node":"mi"},[l("path",{"data-c":"1D456",d:"M184 600Q184 624 203 642T247 661Q265 661 277 649T290 619Q290 596 270 577T226 557Q211 557 198 567T184 600ZM21 287Q21 295 30 318T54 369T98 420T158 442Q197 442 223 419T250 357Q250 340 236 301T196 196T154 83Q149 61 149 51Q149 26 166 26Q175 26 185 29T208 43T235 78T260 137Q263 149 265 151T282 153Q302 153 302 143Q302 135 293 112T268 61T223 11T161 -11Q129 -11 102 10T74 74Q74 91 79 106T122 220Q160 321 166 341T173 380Q173 404 156 404H154Q124 404 99 371T61 287Q60 286 59 284T58 281T56 279T53 278T49 278T41 278H27Q21 284 21 287Z",style:{"stroke-width":"3"}})])])],-1)])])),t[1]||(t[1]=l("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[l("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[l("mi",null,"i")])],-1))])]),t[14]||(t[14]=i('<table tabindex="0"><thead><tr><th>访问位</th><th>修改位</th><th>保护位</th><th>驻留位</th><th>物理页帧号</th></tr></thead></table><ul><li><p><strong>驻留位（Present）：</strong> 1表示该页位于内存当中；0表示该页当前还在外存当中。</p></li><li><p><strong>保护位：</strong> 只读、可写、可执行。</p></li><li><p><strong>修改位（Dirty）：</strong> 表明此页在内存中是否被修改过。</p></li><li><p><strong>访问（统计）位（Accessed）：</strong> 用于页面置换算法。</p></li></ul><p>常见分配：</p><ul><li>用户可执行文件以文件形式存储在硬盘中</li><li>堆栈在磁盘上没有对应文件，地址为空</li><li>未分配部分没有对应页表项，申请时才会建立相应页表项</li></ul><h2 id="页面调入策略" tabindex="-1">页面调入策略 <a class="header-anchor" href="#页面调入策略" aria-label="Permalink to &quot;页面调入策略&quot;">​</a></h2><p><strong>核心思想：</strong> 只需把<strong>当前需要的部分页面</strong>调入主存</p>',6)),l("ul",null,[t[6]||(t[6]=l("li",null,"调入什么：OS核心部分、正在运行的用户进程相关程序和数据",-1)),l("li",null,[t[4]||(t[4]=a("何时调入：OS在系统启动时调入；用户程序取决于调入策略（预调页，按需调页，",-1)),l("mjx-container",x,[(e(),o("svg",T,[...t[2]||(t[2]=[l("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[l("g",{"data-mml-node":"math"},[l("g",{"data-mml-node":"mo"},[l("path",{"data-c":"2026",d:"M78 60Q78 84 95 102T138 120Q162 120 180 104T199 61Q199 36 182 18T139 0T96 17T78 60ZM525 60Q525 84 542 102T585 120Q609 120 627 104T646 61Q646 36 629 18T586 0T543 17T525 60ZM972 60Q972 84 989 102T1032 120Q1056 120 1074 104T1093 61Q1093 36 1076 18T1033 0T990 17T972 60Z",style:{"stroke-width":"3"}})])])],-1)])])),t[3]||(t[3]=l("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[l("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[l("mo",null,"…")])],-1))]),t[5]||(t[5]=a("）",-1))]),t[7]||(t[7]=l("li",null,"如何调入：缺页错误处理机制",-1))]),t[15]||(t[15]=i('<h3 id="按需调页-请求式调页" tabindex="-1">按需调页（请求式调页） <a class="header-anchor" href="#按需调页-请求式调页" aria-label="Permalink to &quot;按需调页（请求式调页）&quot;">​</a></h3><p>需要某页时调入，进程执行时使用懒惰交换（直到要用到了再写入）；外存保护不再内存中的页</p><h3 id="预调页" tabindex="-1">预调页 <a class="header-anchor" href="#预调页" aria-label="Permalink to &quot;预调页&quot;">​</a></h3><p>可以通过所需要的页一起调入内存，减少缺页错误的数量，增加了效率</p><p>实际应用中可以为当前进程维护一个工作集，如果进程暂停后重启根据工作集一次性调入。</p><p>当然如果程序局部性较差，则会降低系统效率</p><h2 id="缺页错误-page-fault-处理过程" tabindex="-1">缺页错误（Page Fault）处理过程 <a class="header-anchor" href="#缺页错误-page-fault-处理过程" aria-label="Permalink to &quot;缺页错误（Page Fault）处理过程&quot;">​</a></h2><ol><li><strong>现场保护：</strong> 陷入内核态，保存必要信息（OS 及用户进程状态相关）</li><li><strong>页面定位：</strong> 查找出发生缺页异常的虚拟页面，通常保存在一个硬件寄存器中，否则需要检索程序计数器，取出指令，用软件分析</li><li><strong>权限检查：</strong> 检查虚拟地址的有效性及安全保护位，若发生保护错误，杀死该进程</li><li><strong>新页面调入：</strong> 查找一个空闲物理页框调入；如果没有空闲页框则需要通过页面置换算法找出一个需要换出的页框</li><li><strong>旧页面写回：</strong> 若找到的页框被修改了，需要写回到磁盘上</li><li><strong>新页面调入：</strong> 找到的页框无有效映射后，将保存在磁盘上的页面内容复制到该页框中</li><li><strong>更新页表：</strong> 页面内容全部装入页框后，发送一个中断，更新页表项的物理页框号和状态</li><li><strong>恢复现场：</strong> 恢复缺页异常发生前的状态，将程序指针 <strong>重新指向引起缺页异常的指令</strong></li><li><strong>继续执行：</strong> 重新执行引发缺页异常的指令，进行存储访问。</li></ol><h2 id="页面分配策略" tabindex="-1">页面分配策略 <a class="header-anchor" href="#页面分配策略" aria-label="Permalink to &quot;页面分配策略&quot;">​</a></h2><h3 id="工作集与驻留集管理" tabindex="-1">工作集与驻留集管理 <a class="header-anchor" href="#工作集与驻留集管理" aria-label="Permalink to &quot;工作集与驻留集管理&quot;">​</a></h3><p><strong>工作集：</strong> 进程运行正在使用的页面集合</p>',11)),l("p",null,[t[10]||(t[10]=l("strong",null,"驻留集：",-1)),t[11]||(t[11]=a(" 虚拟存储系统中，每个进程驻留在内存的页面集合，或进程分到的物理页框集合 （工作集 ",-1)),l("mjx-container",b,[(e(),o("svg",_,[...t[8]||(t[8]=[l("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[l("g",{"data-mml-node":"math"},[l("g",{"data-mml-node":"mo"},[l("path",{"data-c":"2208",d:"M84 250Q84 372 166 450T360 539Q361 539 377 539T419 540T469 540H568Q583 532 583 520Q583 511 570 501L466 500Q355 499 329 494Q280 482 242 458T183 409T147 354T129 306T124 272V270H568Q583 262 583 250T568 230H124V228Q124 207 134 177T167 112T231 48T328 7Q355 1 466 0H570Q583 -10 583 -20Q583 -32 568 -40H471Q464 -40 446 -40T417 -41Q262 -41 172 45Q84 127 84 250Z",style:{"stroke-width":"3"}})])])],-1)])])),t[9]||(t[9]=l("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[l("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[l("mo",null,"∈")])],-1))]),t[12]||(t[12]=a(" 驻留集）",-1))]),t[16]||(t[16]=i('<p><strong>影响页框分配的主要因素：</strong></p><ul><li>分配给每个活动进程的页框数越少，能够驻留内存的活动进程数就越多，进程调度程序能调度就绪进程的概率就越大，然而，这将导致进程发生缺页异常的概率较大；</li><li>为进程分配过多的页框，并发运行的进程数降低，影响系统资源利用率。</li></ul><h3 id="页面分配策略-固定分配策略" tabindex="-1">页面分配策略-固定分配策略 <a class="header-anchor" href="#页面分配策略-固定分配策略" aria-label="Permalink to &quot;页面分配策略-固定分配策略&quot;">​</a></h3><p>为每个活动进程分配固定数量的页框。即每个进程的驻留集大小在运行期间固定不变。</p><p>分多少？</p><ul><li>系统根据进程类型</li><li>编程人员或系统管理员指定</li></ul><p>不够怎么办？</p><p>只能从分给该进程的内存块中进行页面置换</p><h3 id="页面分配策略-可变分配策略" tabindex="-1">页面分配策略-可变分配策略 <a class="header-anchor" href="#页面分配策略-可变分配策略" aria-label="Permalink to &quot;页面分配策略-可变分配策略&quot;">​</a></h3><p>可根据进程的缺页率调整进程的驻留集</p><ul><li>缺页率很高时，驻留集太小，需增加页框</li><li>当缺页率一段时间内都保持很低时，可以在不会明显增加进程缺页率的前提下，回收其一部分页框，减小进程的驻留集</li></ul><p><strong>特点：</strong></p><ul><li>灵活，吞吐量高，有效利用内存</li><li>要求统计缺页率，增加开销；且阈值确定较复杂</li><li>需要操作系统软件和处理机平台硬件的支持</li></ul><h3 id="内存块初始分配方法" tabindex="-1">内存块初始分配方法 <a class="header-anchor" href="#内存块初始分配方法" aria-label="Permalink to &quot;内存块初始分配方法&quot;">​</a></h3><p><strong>等分法：</strong> 为每个进程分配存储块的最简单的办法是平分，即若有m块、n个进程，则每个进程分m/n块（其值向下取整）</p><p><strong>比例法：</strong> 分给进程的块数=（进程地址空间大小/全部进程的总地址空间）*可用块总数</p><p><strong>优先权法：</strong>为加速高优先级进程的执行，可以给高优先级进程分较多内存。如使用比例分配法时，分给进程的块数不仅取决于程序的相对大小，而且也取决于优先级的高低。</p><h3 id="抖动问题-thrashing" tabindex="-1">抖动问题(thrashing) <a class="header-anchor" href="#抖动问题-thrashing" aria-label="Permalink to &quot;抖动问题(thrashing)&quot;">​</a></h3><p>随着驻留内存的进程数目增加，即进程并发程度的提高，处理器利用率先上升，然后下降。</p><p><img src="'+p+'" alt="抖动问题"></p><ul><li>第一段：并发度上升，处理器利用率增加</li><li>第二段：驻留集小于工作集后，缺页率急剧上升，频繁调页使得调页开销增大</li></ul><p><strong>抖动问题的消除与预防：</strong></p><ul><li>局部替换策略：将抖动局限于进程的驻留集内，不影响其他进程，未解决问题，只是减小影响</li><li>工作集算法：<a href="#工作集算法">下文</a>提到，减小缺页率</li><li>预留部分页面：减小缺页率</li><li>挂起若干进程：减小并发度，让抖动进程回归正常 1</li></ul><h2 id="页面置换和页面置换策略" tabindex="-1">页面置换和页面置换策略 <a class="header-anchor" href="#页面置换和页面置换策略" aria-label="Permalink to &quot;页面置换和页面置换策略&quot;">​</a></h2><p><strong>问题：</strong> 当发生缺页异常时</p><ul><li>在什么范围判断已经没有空闲页框？</li><li>如果指定范围没有空闲页框，应该选什么页面移出内存？</li></ul><h3 id="置换范围" tabindex="-1">置换范围 <a class="header-anchor" href="#置换范围" aria-label="Permalink to &quot;置换范围&quot;">​</a></h3><p><strong>局部置换策略：</strong> 系统在进程自身的驻留集中判断当前是否存在空闲页框，并在其中进行置换。</p><p><strong>全局置换策略：</strong> 在整个内存空间内判断有无空闲页框，并允许从其它进程的驻留集中选择一个页面换出内存。</p><ul><li>问题：无法控制缺页率。进程缺页率和其他进程有关，受外部影响大</li></ul><h3 id="选页" tabindex="-1">选页 <a class="header-anchor" href="#选页" aria-label="Permalink to &quot;选页&quot;">​</a></h3><p><strong>选页标准：</strong> 减少页面换入换出频率；选择替换页面的过程复杂度低</p><p><strong>常用方法：</strong></p><ul><li>最优置换（OPT）：算法将内存中的页 P 置换掉，页 P 满足：从现在开始到未来某刻再次需要页P，这段时间最长。也就是 OPT 算法会<strong>置换掉未来最久不被使用</strong>的页。因为需要知道未来的使用情况，<strong>实际上无法实现</strong>，只能作为一种比较标准。</li><li>先进先出（FIFO）：系统记录每个页被调入内存的时间，当必需置换掉某页时，<strong>选择最旧的页换出</strong>。性能较低，会出现 Belady 现象。</li><li>最近最少使用（LRU）：原理是最近访问的页面未来被访问的概率会更高（局部性原理）。开销较大，有近似算法。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Belady 现象与改进方案</strong> Belady’s Anomaly: 在使用FIFO算法作为缺页置换算法时，随着分配的页框增多，缺页率反而提高 其出现的原因是决策因素只考虑第一次出现的时间，但是与实际出现频率等无关，违背了局部性原理 <strong>改进方案：</strong></p><ul><li>Second Chance: 增加一个标志位，如果添加后再被访问过，则要被置换时考虑再给一次机会，移除并放在队尾</li><li>Clock: Second Chance 的环形队列改进，避免将数据在FIFO队列中移动</li></ul></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>LRU 的实现：</strong></p><ul><li>一种软件的实现方法：链表法</li><li>一种硬件的实现方法：计数器</li><li>一种近似算法：老化算法（AGING）</li></ul></div><h3 id="工作集算法" tabindex="-1">工作集算法 <a class="header-anchor" href="#工作集算法" aria-label="Permalink to &quot;工作集算法&quot;">​</a></h3><p>随着程序运行当内存访问的局部性区域的位置大致稳定时，工作集大小也大致稳定</p><p>局部性区域的位置改变时，工作集快速扩张和收缩过渡到下一个稳定值</p><p><img src="'+h+'" alt="工作集原理"></p><p><strong>算法：</strong> 记录进程的工作集，优先选择不在工作集的页面替换</p><p><strong>挑战：</strong> 工作集的确定，精确记录困难，粗糙集合太大，且工作集也未必能准确反映未来情况</p><h3 id="替换策略具体实现" tabindex="-1">替换策略具体实现 <a class="header-anchor" href="#替换策略具体实现" aria-label="Permalink to &quot;替换策略具体实现&quot;">​</a></h3><p>以下是总结，需要<strong>注意实现过程</strong></p><table tabindex="0"><thead><tr><th>算法</th><th>实现</th><th>效果</th></tr></thead><tbody><tr><td>OPT</td><td>无法实现，作为标准</td><td>最理想</td></tr><tr><td>FIFO</td><td>新访问的页面插入FIFO队列尾部，页面在FIFO队列中顺序移动；需要置换时淘汰FIFO队列头部的页面；</td><td>最简单，效果最差，会出现Belady现象</td></tr><tr><td>Second Chance</td><td>每个页面增加一个访问标志位，用于标识此数据装入内存后是否被再次访问过。需要置换时从队头扫描，并对标识位为 1 的页置为 0 ，直到找到标识位为 0 ，如果找到队尾都没有，则在扫描一次（按照 FIFO 原则）</td><td>效果比 FIFO 好，但代价和复杂度比较大</td></tr><tr><td>Clock</td><td>Second Chance 的循环队列改进，注意使用了一个指针，每次找替换页不是从头开始，而是从指针位置开始</td><td>效果和 Second Chance 相同，代价和复杂度比较小</td></tr><tr><td>LRU 链表实现（软件）</td><td>每次访问页面时若链表内不存在则创建，若链表内存在则取出插入到头部，每次淘汰尾部</td><td>开销大，效果好</td></tr><tr><td>LRU 计数器实现（硬件）</td><td>设置指令计数器，每个页面在被访问时读取计数器，并记录相应数值（指令运行的时间戳）。淘汰计数值最小的页面。</td><td>开销大，效果好</td></tr><tr><td>Aging</td><td>为每个页面设置一个移位寄存器，每隔一段时间，所有寄存器右移1位，并将访问位 R 值从左移入。淘汰寄存器中数值最小的页面。</td><td>效果与 LRU 相近，开销较小</td></tr></tbody></table><p><img src="'+g+'" alt="页面替换算法"></p><h2 id="更新问题" tabindex="-1">更新问题 <a class="header-anchor" href="#更新问题" aria-label="Permalink to &quot;更新问题&quot;">​</a></h2><p>在虚存系统中，主存作为辅存（磁盘）的高速缓存，保存了磁盘信息的副本。因此，当一个页面被换出时，为了保持主辅存信息的一致性，必要时需要信息更新：</p><ul><li>若换出页面是file backed类型，且未被修改，则直接丢弃，因为磁盘上保存有相同的副本。</li><li>若换出页面是file backed的类型，但已被修改，则直接写回原有位置。</li><li>若换出页面是anonymous类型，若是第一次换出或已被修改，则写入swap区;若非第一次换出且未被修改,则丢弃。</li></ul><h2 id="复习题" tabindex="-1">复习题 <a class="header-anchor" href="#复习题" aria-label="Permalink to &quot;复习题&quot;">​</a></h2>',50)),d(r,{collection:"final-review"})])}const y=n(u,[["render",w]]);export{S as __pageData,y as default};
